        return {}
    ret30 = cur - past30
    ret10 = cur - past10 if np.isfinite(past10) else 0.0
    # rolling vol of avg changes
    # compute diff where both finite
    rets = []
    for i in range(1, len(avg)):
        if np.isfinite(avg[i]) and np.isfinite(avg[i-1]):
            rets.append(float(avg[i] - avg[i-1]))
    if len(rets) < 20:
